package org.example.kotlineditor.compression

/** Dictionaries shipped with the application. */
object Dictionaries {
    /**
     * 64 KiB dictionary trained on public Kotlin and PHP sources, then on their wire representation (lines
     * prefixed by their length). It is the default for code bodies; a per-project dictionary can replace it
     * later without changing the frame format, because zstd writes the dictionary id in each frame.
     *
     * Generated by `benchmark/train-dictionaries.sh` and copied by `compression/scripts/update-dictionary.sh`.
     */
    val generic: ByteArray by lazy {
        val stream = Dictionaries::class.java.getResourceAsStream("/zstd/mixed-64k.dict")
        requireNotNull(stream) { "Missing resource /zstd/mixed-64k.dict" }.use { it.readBytes() }
    }
}
